  gamma2.^3+11.*gamma2.^4).*eta(1).^(2.*gamma2).*eta(2).^(2.*gamma2) ...
  +(-1).*((-96)+50.*gamma2+35.*gamma2.^2+10.*gamma2.^3+gamma2.^4).* ...
