  gamma2.*eta(1).^((-4)+gamma2).*eta(2).^((-1)+gamma2).*(eta(1) ...
  .^gamma2+eta(2).^gamma2).^(-5).*((6+11.*gamma2+6.*gamma2.^2+ ...
  gamma2.^3).*eta(1).^(3.*gamma2)+(18+11.*gamma2+(-18).*gamma2.^2+( ...
  -11).*gamma2.^3).*eta(1).^(2.*gamma2).*eta(2).^gamma2+(18+(-11).* ...
  gamma2+(-18).*gamma2.^2+11.*gamma2.^3).*eta(1).^gamma2.*eta(2).^( ...
  2.*gamma2)+(-1).*((-6)+11.*gamma2+(-6).*gamma2.^2+gamma2.^3).*eta( ...
  2).^(3.*gamma2));0,0,(-1).*gamma2.*eta(1).^((-1)+gamma2).*eta(2) ...
  .^((-4)+gamma2).*(eta(1).^gamma2+eta(2).^gamma2).^(-5).*(((-6)+ ...
  11.*gamma2+(-6).*gamma2.^2+gamma2.^3).*eta(1).^(3.*gamma2)+((-18)+ ...
  11.*gamma2+18.*gamma2.^2+(-11).*gamma2.^3).*eta(1).^(2.*gamma2).* ...
  eta(2).^gamma2+((-18)+(-11).*gamma2+18.*gamma2.^2+11.*gamma2.^3).* ...
  eta(1).^gamma2.*eta(2).^(2.*gamma2)+(-1).*(6+11.*gamma2+6.* ...
  gamma2.^2+gamma2.^3).*eta(2).^(3.*gamma2));0,0,(-1).*gamma2.*eta( ...
  1).^((-3)+gamma2).*eta(2).^((-2)+gamma2).*(eta(1).^gamma2+eta(2) ...
  .^gamma2).^(-5).*(((-2)+(-1).*gamma2+2.*gamma2.^2+gamma2.^3).*eta( ...
